    .map(([key, group]) => {
      const descriptor = descriptorsByKey.get(key);
      if (!descriptor)
        throw new Error(
          `Collection report has no snapshot descriptor for ${group[0].source.repoId}@${group[0].source.revision}`,
        );
      if (
        group.some(
          (sample) => sample.source.snapshotHash !== descriptor.snapshotHash,
        )
      )
        throw new Error(
          `Corpus snapshot hash disagrees with collection report for ${descriptor.repoId}@${descriptor.revision}`,
        );
      return {
        repoId: descriptor.repoId,
        revision: descriptor.revision,
        subtree: descriptor.subtree,
        samples: group,
      };
    })

[...groups.entries()]
    .map(([key, members]) => {
      const evidence = members[0].state.request.evidence;
      const descriptor = descriptors.get(key);
      if (!descriptor)
        throw new Error(
          `No source snapshot descriptor for ${evidence.repoId}@${evidence.worktreeId}.`,
        );
      if (
        members.some(
          ({ state }) =>
            state.request.evidence.repoId !== descriptor.repoId ||
            state.request.evidence.worktreeId !== descriptor.revision ||
            state.request.evidence.snapshotHash !== descriptor.snapshotHash,
        )
      )
        throw new Error(`Inconsistent snapshot group ${key}.`);
      return {
        repoId: descriptor.repoId,
        revision: descriptor.revision,
        snapshotHash: descriptor.snapshotHash,
        descriptor,
        pairs: members,
      };
    })

